-- 5004 🏋️ Exercises from the book "xabi-alonso-82-passing-positional-possession-games-patterns-and-attacking-practi" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'xabi-alonso-82-passing-positional-possession-games-patterns-and-attacking-practi');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Octagon dribble, pass and swap positions', 'warm_up', 'unopposed', NULL, 29, 29, 'Warm Ups 1', 'Xabi Alonso (Bayer Leverkusen)', 'Activation with dribbling in traffic, scanning and passing to a free team-mate.', 'Octagon of cones with a centre circle marked by mannequins; 8 inside players with balls start outside the octagon, the other players stand on the octagon points.', 'Inside players dribble through the mannequin circle, then pass to any free outside player and follow the pass out to take their spot; the receiver then goes in and repeats.', NULL, NULL, 'Keep the ball close and avoid team-mates in the centre; lift the head to find a free player.', '8 dribblers + outside players (about 16)', 16, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 10),
  ('Octagon dribble, one-two and lay-off swap', 'warm_up', 'unopposed', NULL, 30, 30, 'Warm Ups 2', 'Xabi Alonso (Bayer Leverkusen)', 'Activation adding a wall pass and a set-back to the dribbling warm-up.', 'Same octagon and mannequin centre circle as Warm Up 1; 8 reds with balls inside, whites on the outside.', 'A red dribbles through the centre, plays a one-two with a free outside white, then lays the ball off for the white to step onto and goes out to take his place; the white dribbles through the centre and passes to a free red outside. Continuous.', NULL, NULL, NULL, 'about 16', 16, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 20),
  ('Three-channel footwork and coach one-twos', 'warm_up', 'unopposed', NULL, 31, 31, 'Warm Ups 3', 'Xabi Alonso (Bayer Leverkusen)', 'Dynamic movement, quick feet and short return passes before sprinting.', '20-yard long area split into 3 channels, each with yellow cones, blue cones and a mannequin with a coach beside it; a small group queues at the start of each channel.', 'Phase 3: quick feet forward/back in and out of 3 yellow cones, quick feet through 3 blue cones, run to the mannequin, the coach feeds a ground ball either side for two one-twos, sprint to the end and jog back.', '6 minutes in total across 3 phases.', 'Phase 1: lateral high steps through yellow cones, butt kicks through blue cones, headers back to the coach. Phase 2: lateral high steps, high knees over blue cones, alternate-foot volleys back to the coach.', NULL, '3 groups of about 4', 9, 15, '20 yards long, 3 channels', 18.3, NULL, 6.0, false, false, false, NULL, 30),
  ('Hurdle, pass between mannequins and dribble', 'warm_up', 'unopposed', NULL, 32, 32, 'Warm Ups 4', 'Xabi Alonso (Bayer Leverkusen)', 'Speed and agility work combined with passing, timing of movement and directional first touch.', '15-yard channels, groups of 4; a red hurdle at the start, two mannequins mid-channel, B with ball at the far end facing A.', 'A skips over the hurdle and runs forward; B passes between the mannequins, A steps to meet it and passes back; A sprints back to the hurdle and returns; B passes through again and A takes a directional first touch past a mannequin and dribbles to the end while B jogs to swap ends. Next pair repeats.', 'Work 1 minute, then dynamic stretching led by the coach.', NULL, NULL, 'groups of 4', 4, NULL, '15 yard channels', 13.7, NULL, NULL, false, false, false, NULL, 40),
  ('Hurdle footwork, set-back and run round mannequin', 'warm_up', 'unopposed', NULL, 33, 33, 'Warm Ups 5', 'Xabi Alonso (Bayer Leverkusen)', 'Progressed agility warm-up with one-twos, headers and receiving on the move.', 'As Warm Up 4: 15-yard channels with hurdle, small yellow hurdles, two mannequins; groups of 4.', 'Progression 1: A skips the hurdle, outside-foot over and back on the small hurdles; B passes between the mannequins, A plays it back, B sets it for A to run round a mannequin, receive and dribble to the end. B then jogs to switch ends.', '1 minute work then dynamic stretching.', 'Progression 2: A skips the hurdle with a one-leg hop and pause; B throws for A to jump and head back, then sets the ball for A to run round the mannequin, receive and dribble to the end.', NULL, 'groups of 4', 4, NULL, '15 yard channels', 13.7, NULL, NULL, false, false, false, NULL, 50),
  ('Cone footwork, volleys and three-pass combo', 'warm_up', 'unopposed', NULL, 34, 34, 'Warm Ups 6', 'Xabi Alonso (Bayer Leverkusen)', 'Varied technical actions (pass, volley, header, dribble) with speed and agility.', '15-yard channels with cones, hurdle and two mannequins; groups of 4, A working and B serving.', 'Variation 1: A steps over 3 cones, side-steps a hurdle, touches a mannequin and drops back at an angle; B passes, A touches wide of the other mannequin and dribbles to the end. Variation 2: A moves sideways through cones and hurdle, then plays a 3-pass combination with B and on the third pass touches wide of a mannequin and dribbles away.', 'B jogs to the far side to switch ends; next pair goes.', 'Variation 3: B throws for A to volley back, then sets the ball for A to run round a mannequin and dribble off. Variation 3b: jump and head back between the mannequins.', NULL, 'groups of 4', 4, NULL, '15 yard channels', 13.7, NULL, NULL, false, false, false, NULL, 60),
  ('Seven-cone pass and follow circuit', 'passing_unopposed', 'unopposed', NULL, 35, 35, 'Warm Ups 7', 'Xabi Alonso (Bayer Leverkusen)', 'Two-touch passing on the move with a one-two and running with the ball.', 'Half pitch with 7 cones zig-zagging up each side, a player on each cone; two groups play at once, one ball each.', 'Players pass to the next cone and follow their pass; at the sixth cone a one-two is played with the seventh player, who then carries the ball across to the start of the other group''s line.', '2 touches; everyone follows their pass.', NULL, 'Step slightly off the cone to meet the ball; two touches to receive and pass; stay sharp.', '2 groups of 7+', 14, NULL, 'half pitch', NULL, NULL, NULL, false, false, false, NULL, 70),
  ('One-touch triangle with hurdle coordination', 'passing_unopposed', 'unopposed', NULL, 36, 36, 'Warm Ups 8', 'Xabi Alonso (Bayer Leverkusen)', 'One-touch passing with body facing the target, plus a footwork task before receiving.', 'Large triangle of cones A, B and C; small hurdle and mannequin at C; group of 7 spread across the positions.', 'A passes to B, B one-touch to C; C does quick steps and lifts the left foot over the hurdle to touch the ground and back, then moves in front of the mannequin to meet B''s pass and returns it first time to the start. Players rotate A to B to C to A.', '1 touch; switch to anti-clockwise after 1-2 minutes.', NULL, 'One touch throughout, body open to where the ball is going.', 'groups of 7', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 80),
  ('Triangle with hurdle and directional first touch', 'passing_unopposed', 'unopposed', NULL, 37, 37, 'Warm Ups 9', 'Xabi Alonso (Bayer Leverkusen)', 'Receiving with a directional touch behind a mannequin after a coordination task.', 'Same triangle as Warm Up 8 with hurdle and mannequin at C; groups of 7.', 'A passes to B, B one-touch to C; C clears the hurdle footwork, takes B''s pass with a directional touch behind the mannequin and passes back to the start with the second touch. Rotate A to B to C to A.', 'C uses 2 touches, others 1; change direction after 1-2 minutes.', NULL, NULL, 'groups of 7', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 90),
  ('Triangle give-and-go under coach pressure', 'passing_opposed', 'passive', 'in_possession', 38, 38, 'Warm Ups 10', 'Xabi Alonso (Bayer Leverkusen)', 'One-touch passing and a give-and-go with light pressure on the receiver.', 'Same triangle as Warm Up 8 with hurdle and mannequin at C; coach acts as passive defender; groups of 7.', 'A passes to B, B one-touch to C; after the hurdle footwork C steps in front of the mannequin and sets the ball back for B, who has moved forward under the coach''s passive pressure; B returns it for C, who has spun round the mannequin, and C passes to the start. Rotate A to B to C to A.', 'Change direction after 1-2 minutes.', NULL, NULL, 'groups of 7 + coach', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 100),
  ('Four-corner rings, poles and passing circuit', 'passing_unopposed', 'unopposed', NULL, 39, 39, 'Warm Ups 11', 'Xabi Alonso (Bayer Leverkusen)', 'Dynamic speed and agility movements linked to diagonal passing around a square.', 'Square with 4 starting positions A-D; speed rings at A and C, two angled poles to step over and upright poles at B and D; balls at A.', 'A side-steps through the rings, passes to B and runs diagonally round a pole to B''s spot; B passes to C and runs to the angled poles, lifting a leg over each alternately, then jogs to C; C and B/D repeat the pattern on the other side back to A. Players keep rotating A-B-C-D-A.', NULL, NULL, NULL, NULL, 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 110),
  ('Four-station SAQ circuit (no ball)', 'warm_up', 'unopposed', NULL, 40, 40, 'Warm Ups 12', 'Xabi Alonso (Bayer Leverkusen)', 'Speed, agility and quickness with sharp changes of direction.', 'Square with 4 stations (yellow, blue, white, red) on the sides: ground poles and an upright pole, or hurdles and crossed X poles; 4 players per station.', 'All stations go at once. Yellow: lateral steps through ground poles, run right of the pole, cut sharply left, run to the blue station. Blue: steps over hurdles, jump the X poles, run to red. White as blue, then run to yellow. Red as yellow but pole on the left, then run to white.', 'Work 1 minute, stretch, repeat faster for 1 minute; avoid others crossing in the middle.', 'Moves on to the same circuit with 2 balls added (Warm Up 13).', NULL, '16 (4 stations of 4)', 16, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 120),
  ('Four-station SAQ circuit with passing', 'warm_up', 'unopposed', NULL, 41, 42, 'Warm Ups 13', 'Xabi Alonso (Bayer Leverkusen)', 'Agility circuit with a pass across the square before each movement.', 'Same 4-station square as Warm Up 12 with balls added.', 'Each player passes to the next waiting player at the station they are about to run to, then does their station''s footwork and runs there: yellow passes to red, blue to white, white to blue, red to yellow.', '1 minute (passing before moving), 30 seconds rest, then 1 minute where yellows and reds go through the ground poles before passing.', 'Variation: ground pole angles and positions changed by the coach after each round, and two upright poles for reds and yellows to slalom through before passing; blues and whites pass before their hurdles and X poles.', NULL, '16 (4 stations of 4)', 16, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 130),
  ('Pass, volley and header conditioning circuit', 'warm_up', 'unopposed', NULL, 43, 44, 'Warm Ups 14', 'Xabi Alonso (Bayer Leverkusen)', 'Technical passing, volleying and heading built into a timed conditioning circuit.', 'Central square with positions A-D; poles and crossed X poles at the top, mannequins at the bottom, coaches serving at each end.', 'A passes to B, runs round poles to the X poles and volleys back the coach''s throws left and right, then jogs to B; B passes to C, runs diagonally to a mannequin and jumps to head back the coach''s throws, then jogs to C; C and D mirror this on the other side.', '3 min steady, 2 min faster, 3 min (top: 2 passes back; bottom: sprint to line + 1 pass back), 2 min (top: receive and pass back with 2 touches; bottom: jump and header back).', NULL, NULL, NULL, 8, NULL, NULL, NULL, NULL, 10.0, false, false, false, NULL, 140),
  ('Diamond support-play passing combination', 'passing_unopposed', 'unopposed', 'in_possession', 47, 47, 'Passing Combinations 1', 'Xabi Alonso (Bayer Leverkusen)', 'Timing of movement off a mannequin to support and combine at one touch.', 'Diamond with 4 mannequins in the middle; end players E1 and E2 stay at each end, A players queue on one side cone and B players on the other.', 'E1 passes to B1, who comes round a mannequin to meet it; B1 passes to A1, who comes round a mannequin and passes to E2; A1 and B1 return to their cones. E2 then plays the same with B2 and A2 back to E1.', '1 touch throughout.', NULL, NULL, NULL, 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 150),
  ('Diamond combination, one-two under pressure', 'passing_opposed', 'passive', 'in_possession', 48, 48, 'Passing Combinations 2', 'Xabi Alonso (Bayer Leverkusen)', 'Support play and set-backs while a coach pressures the receiver.', 'Same diamond and mannequins as Passing Combinations 1; coach in the middle as passive defender.', 'E1 plays a one-two with A1, who drops to meet it while pressed by the coach; E1 then passes to B1, who comes round a mannequin and sets it for A1 to move onto; A1 passes to E2. A1 and B1 go back to their cones and E2 repeats with A2 and B2.', '1 touch throughout.', NULL, NULL, NULL, 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 160),
  ('Diamond combination, escape the coach', 'passing_opposed', 'passive', 'in_possession', 49, 49, 'Passing Combinations 3', 'Xabi Alonso (Bayer Leverkusen)', 'Receiving under pressure and combining with a third man to play forward.', 'Same diamond and mannequins; coach applies pressure in the middle.', 'E1 passes to A1, who drops to meet it under pressure; A1 plays a one-two with B1, who comes round a mannequin and sets it back; A1 passes to E2. Then the same from E2 with A2 and B2.', '1 touch throughout.', 'Extra pressure: players must get away from the coach; option to play straight into the centre player (B1) instead of back to E1.', NULL, NULL, 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 170),
  ('Pass and move with rotating central player', 'passing_unopposed', 'unopposed', 'in_possession', 50, 50, 'Passing Combinations 4', 'Xabi Alonso (Bayer Leverkusen)', 'Combination play through a central link player who changes after each sequence.', 'Square of cones with a central position B; outside positions A, C, D, E; balls at A.', 'A plays a one-two with B then passes to C; A becomes the new centre player and B moves to C. C passes to D, D to the centre (A), who sets it back for D to pass to E; D then becomes the centre player. E passes to the next player at A, who finds the centre player, and so on.', 'C and E do side-to-side footwork before receiving.', NULL, NULL, NULL, 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 180),
  ('Diamond give-and-go with two passive defenders', 'passing_opposed', 'passive', 'in_possession', 51, 51, 'Passing Combinations 5', 'Xabi Alonso (Bayer Leverkusen)', 'One-twos, give-and-goes and directional first touches away from pressure.', 'Diamond with positions A (start), B (centre), C and E (sides, by mannequins), D (top); two passive defenders DP1 behind B and DP2 near D.', 'A passes to B, who sets back for A stepping forward while pressed by DP1; B passes wide to C, who drops off his cone; C plays a give-and-go with B moving across; C passes to D, who is pressed by DP2 and turns away with a directional touch; D passes to E, who drops off and takes a directional touch, then passes to the start. Rotate A-B-C-D-E-A.', 'Switch to clockwise after a few minutes.', NULL, 'Defenders give realistic pressure; good directional first touch away from it.', 'about 7 + 2 passive defenders', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 190),
  ('Diamond give-and-goes with switch of play', 'passing_opposed', 'passive', 'in_possession', 52, 52, 'Passing Combinations 6', 'Xabi Alonso (Bayer Leverkusen)', 'Combining around pressure and switching play across the diamond.', 'Same diamond as Passing Combinations 5 with passive defenders DP1 and DP2.', 'A-B set-back and B to C as before, then C plays a give-and-go with B; C switches play across to E, who sets for D; D checks off his cone to draw DP2 then spins to receive; D passes to E, who runs round the mannequin for the second give-and-go, and E passes to the start. Rotate A-B-C-D-E-A.', 'If DP2 is too tight on D, C chooses to play to E.', NULL, NULL, 'about 7 + 2 passive defenders', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 200),
  ('Two-ball circuit with central link players', 'passing_opposed', 'passive', 'in_possession', 53, 53, 'Passing Combinations 7', 'Xabi Alonso (Bayer Leverkusen)', 'One-twos and give-and-goes through central link players under passive pressure.', 'Diamond with a mannequin in the middle; A and D start at opposite ends with a ball each, B and E are central links, C and F are wide; two coaches press C and F.', 'A and D each play a one-two with B/E, then pass wide to C/F; C/F, pressed by a coach, play a give-and-go with B/E moving across, then pass to the next player at D/A. Rotate A-B-C-D-E-F-A.', '2 balls at once; direction switched to clockwise after a few minutes.', NULL, 'Wide players check away from their cone before moving to receive.', 'about 8 + 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 210),
  ('Two-ball circuit, curved run onto pass', 'passing_opposed', 'passive', 'in_possession', 54, 54, 'Passing Combinations 8', 'Xabi Alonso (Bayer Leverkusen)', 'Weighting a forward pass into a curved run after escaping pressure.', 'Same two-ball diamond as Passing Combinations 7; wide players B and E pressed by coaches, C and F central.', 'A/D play a one-two with the central C/F, then pass wide to B/E; B/E check off their cone, are pressed by a coach, open up and pass with the right weight into the forward curved run of C/F; C/F pass to the next player at D/A. Rotate A-B-C-D-E-F-A.', '2 balls at once.', NULL, 'Check away before receiving; correct weight on the pass for the curved run.', 'about 8 + 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 220),
  ('End-to-end combinations to break lines', 'passing_unopposed', 'unopposed', 'in_possession', 55, 55, 'Passing Combinations 9', 'Xabi Alonso (Bayer Leverkusen)', 'Third-man combinations and set-backs to progress the ball end to end through lines.', 'Long area with A at one end and D at the other; two players each in positions B, C, E and F staggered up both sides, rotating in and out.', 'A plays a one-two with B, passes forward to C who drops, C sets back for B to find D; D plays a one-two with E, passes forward to F who comes to meet it, F sets for E to finish the sequence with a pass to A. Then the mirror image down the other side.', 'Players step out after their 1-2 pass contribution.', NULL, 'Play short and go.', '10 (A, D + 2 each in B, C, E, F)', 10, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 230),
  ('End-to-end combinations, free sequences', 'passing_unopposed', 'unopposed', 'in_possession', 56, 56, 'Passing Combinations 10', 'Xabi Alonso (Bayer Leverkusen)', 'Players invent their own combinations to break lines, building decision making.', 'Same end-to-end layout as Passing Combinations 9.', 'Example: A one-two with B, forward to C who drops, C sets for B to D, D to E and back to C, C diagonal to F who sets for E to play A; A to E2 who sets for F2 to D, D short to E2 who plays diagonally to B2. Continuous, players choose their own patterns.', 'Players step out after 1-2 passes.', NULL, 'Get a feel for the ball; vary the sequences.', '10', 10, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 240),
  ('End to end midfield-breaking circuit, version 1', 'passing_opposed', 'passive', 'in_possession', 69, 69, 'Positional Build Up Play Combinations 1', 'Xabi Alonso (Bayer Leverkusen)', 'Build up with a one-two and a set, then a through pass between mannequins to break the midfield line.', 'Long area with a line of 4 mannequins across the middle as the midfield line; queues of A at both ends, B, C and D stations in each half, a ball at each end; two coaches give passive pressure on B.', 'Runs from both ends at once: A one-twos with B (coach pressing B forces the return), A plays forward to C who sets for B moving onto it, B threads a pass between the mannequins for D running in behind, and D dribbles to the A queue at the far end.', 'Rotate A to B to C to D to A.', NULL, 'Weight the through pass for the run; time D''s run in behind the line.', 'Groups of 4 roles from each end plus 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 250),
  ('End to end midfield-breaking circuit, version 2', 'passing_opposed', 'passive', 'in_possession', 70, 70, 'Positional Build Up Play Combinations 2', 'Xabi Alonso (Bayer Leverkusen)', 'Build up via a one-two then a wide pass, with the wide player finding a run in behind the midfield line.', 'Same area as version 1: mannequin line across the middle, A queues at each end with B, C and D stations; coaches press B passively.', 'A one-twos with B (coach forces the return), A passes wide to C, C plays in behind the mannequins for D''s timed run (D may go inside or outside the mannequins), and D dribbles to the far A queue.', 'Rotate A to B to C to D to A.', 'After 6 minutes switch the direction to anti-clockwise and repeat both versions mirrored.', NULL, 'Groups of 4 roles from each end plus 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 260),
  ('Build up, through pass and dribble circuit (right side)', 'passing_opposed', 'passive', 'in_possession', 71, 71, 'Positional Build Up Play Combinations 3', 'Xabi Alonso (Bayer Leverkusen)', 'Play out through CB, DM, RCB and AM under passive pressure, then break the midfield line with a through pass to the right wing back.', 'Two halves of a pitch with a mannequin at halfway on each wing; positions CB, DM, RCB, AM and RWB in each half, a ball at each end; Alonso and coaches give passive pressure from behind.', 'From both ends at once: CB to DM (pressed), DM to RCB, RCB one-touch to AM, AM (pressed) sets back for DM, DM plays a through pass into the other half for the RWB''s forward run, and the RWB dribbles to the CB spot at the far end.', 'RCB uses 1 touch. Rotate CB to DM to RCB to AM to RWB to CB.', NULL, NULL, '5 positions per half plus coaches', 10, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 270),
  ('Build up and through pass circuit (left side)', 'passing_opposed', 'passive', 'in_possession', 72, 72, 'Positional Build Up Play Combinations 4', 'Xabi Alonso (Bayer Leverkusen)', 'Same build up and midfield-breaking pattern as the right-side circuit but played down the left, finishing with a first-time pass.', 'Two halves with wing mannequins; positions CB, DM, LCB, AM and LWB in each half, a ball at each end; coaches press passively from behind.', 'CB to DM, DM to LCB, LCB one-touch to AM, AM sets for DM, DM plays through for the LWB''s run; the LWB passes first time to the CB spot at the far end instead of dribbling.', 'LCB uses 1 touch; LWB finishes with a first-time pass. Rotate CB to DM to LCB to AM to LWB to CB.', NULL, NULL, '5 positions per half plus coaches', 10, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 280),
  ('Build up, switch of play and give-and-go circuit', 'passing_opposed', 'passive', 'in_possession', 73, 73, 'Positional Build Up Play Combinations 5', 'Xabi Alonso (Bayer Leverkusen)', 'Combine through the centre, switch play to the far wing back and use a give-and-go to break the midfield line.', 'Two halves with a mannequin on each wing at halfway; LCB, DM, CB, AM and RWB stations in each half, a ball at each end with LCB; coaches press passively.', 'LCB to DM, DM across to CB (coach pressing), CB forward to AM (pressed from behind) who sets for DM moving onto it, DM switches to the RWB in front of the mannequin, the RWB gives-and-goes with the AM (who has shifted across) after going round the mannequin, then passes to the LCB spot at the far end.', 'Rotate LCB to DM to CB to AM to RWB to LCB.', NULL, NULL, '5 positions per half plus coaches', 10, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 290),
  ('Midfield-breaking circuit with coach pressing cues', 'passing_opposed', 'passive', 'in_possession', 74, 74, 'Positional Build Up Play Combinations 6', 'Xabi Alonso (Bayer Leverkusen)', 'Players read where the coach presses and pick the matching combination to play through.', 'Two halves with wing mannequins; CB, DM, LCB, AM and LWB stations in each half; coaches act as pressing players and change their positioning.', 'Example shown: the coach blocks the pass to DM, so CB plays to AM, DM moves to get the next pass, DM goes wide to the LWB, who gives-and-goes with the AM and passes to the CB spot at the far end. Many different combinations follow from the coach''s position.', 'Rotate CB to DM to LCB to AM to LWB to CB.', 'Next practice shows 2 more pressing examples.', 'Read the pressure before choosing the pass.', '5 positions per half plus coaches', 10, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 300),
  ('Midfield-breaking circuit, two more pressing cues', 'passing_opposed', 'passive', 'in_possession', 75, 75, 'Positional Build Up Play Combinations 7', 'Xabi Alonso (Bayer Leverkusen)', 'Two further pressing pictures for the coach-cued build up circuit, each needing a different route through.', 'Same two-half set-up as practice 6 with CB, DM, LCB, AM and LWB stations and coaches as pressers.', 'Version A: Alonso blocks the pass to AM, so CB finds DM who plays to AM, AM sets back for LCB stepping forward to go wide to the LWB, who gives-and-goes with AM and passes to the far CB spot. Version B: a coach curves his press to block, so CB and DM play four passes to move the ball to AM, AM sets for LCB, then the same wide give-and-go finish.', 'Rotate CB to DM to LCB to AM to LWB to CB.', NULL, NULL, '5 positions per half plus coaches', 10, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 310),
  ('Blocked lanes build up circuit, version 1', 'passing_opposed', 'passive', 'in_possession', 76, 76, 'Positional Build Up Play Combinations 8', 'Xabi Alonso (Bayer Leverkusen)', 'Use the DM as a link to get round a blocked lane and move the ball up to the forward line.', 'Blocked lanes circuit: 3 centre backs (LCB, CB, RCB), DM, two AMs and CF from the 3-4-2-1 set out in a large diamond-like shape, with 2 coaches as passive defenders blocking lanes and Alonso coaching; balls at CB.', 'CB to RCB while a coach blocks the line to AM1; RCB passes inside to DM, who shifts to meet it and plays AM1; AM1 is pressed so goes to CF; CF finds AM2, AM2 back to LCB, and LCB to the next player at CB.', 'Mostly 1-2 touches. Rotate CB to RCB to DM to AM1 to CF to AM2 to LCB to CB.', NULL, 'DM is the link player round the blocked lane; RCB and AM1 decide inside or outside; always offer support.', '7 positional roles plus 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 320),
  ('Blocked lanes build up circuit, version 2', 'passing_opposed', 'passive', 'in_possession', 77, 77, 'Positional Build Up Play Combinations 9', 'Xabi Alonso (Bayer Leverkusen)', 'Chain two link players (AM1 then DM) to get the ball to the striker when lanes are blocked.', 'Blocked lanes circuit: 3 centre backs (LCB, CB, RCB), DM, two AMs and CF from the 3-4-2-1 set out in a large diamond-like shape, with 2 coaches as passive defenders blocking lanes and Alonso coaching; balls at CB.', 'CB to RCB with the inside pass to DM blocked; RCB plays forward to AM1, who is blocked from CF and sets for DM''s forward run; DM plays CF; CF to AM2 (pressed by Alonso), AM2 back to LCB, LCB to the next player at CB.', '1-2 touches as marked. Same 7-position rotation.', NULL, 'AM1 links to DM, DM links to CF.', '7 positional roles plus 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 330),
  ('Blocked lanes build up circuit, version 3', 'passing_opposed', 'passive', 'in_possession', 78, 78, 'Positional Build Up Play Combinations 10', 'Xabi Alonso (Bayer Leverkusen)', 'Striker moves to open a passing angle when the direct lane from the DM is shut, then combines.', 'Blocked lanes circuit: 3 centre backs (LCB, CB, RCB), DM, two AMs and CF from the 3-4-2-1 set out in a large diamond-like shape, with 2 coaches as passive defenders blocking lanes and Alonso coaching; balls at CB.', 'CB to RCB with the inside pass blocked; RCB to AM1 who sets for DM; DM is pressed so the coach blocks the direct lane to CF, so CF moves across to make an angle; DM finds CF, CF one-twos with AM2, then plays LCB, who passes to the next player at CB.', '1-2 touches. Same 7-position rotation.', NULL, 'Forward moves off the blocked line to create the angle.', '7 positional roles plus 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 340),
  ('Blocked lanes build up circuit, version 4', 'passing_opposed', 'passive', 'in_possession', 79, 79, 'Positional Build Up Play Combinations 11', 'Xabi Alonso (Bayer Leverkusen)', 'Use CB-DM to beat the press then switch across the attacking line when the striker is blocked.', 'Blocked lanes circuit: 3 centre backs (LCB, CB, RCB), DM, two AMs and CF from the 3-4-2-1 set out in a large diamond-like shape, with 2 coaches as passive defenders blocking lanes and Alonso coaching; balls at CB.', 'The coach blocks the pass to RCB, so CB plays DM, who plays forward to AM1; a coach blocks CF so AM1 passes across to AM2; AM2 sets for CF''s movement and CF passes to LCB; LCB sets for AM2''s movement and AM2 passes to the next player at CB.', 'Mainly 1 touch. Same 7-position rotation.', NULL, 'Control, pass, quick.', '7 positional roles plus 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 350),
  ('Blocked lanes build up circuit, version 5', 'passing_opposed', 'passive', 'in_possession', 80, 80, 'Positional Build Up Play Combinations 12', 'Xabi Alonso (Bayer Leverkusen)', 'Play direct from the centre back into the attacking midfielder and move the ball quickly across the front.', 'Blocked lanes circuit: 3 centre backs (LCB, CB, RCB), DM, two AMs and CF from the 3-4-2-1 set out in a large diamond-like shape, with 2 coaches as passive defenders blocking lanes and Alonso coaching; balls at CB.', 'CB passes straight to AM1 with the simple pass to DM blocked; another coach blocks CF so AM1 passes across to AM2; AM2 sets for CF who plays LCB; LCB sets for AM2''s movement and AM2 passes to the next player at CB.', '1-2 touches. Same 7-position rotation.', NULL, 'Attack the space when the direct line is open.', '7 positional roles plus 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 360),
  ('Blocked lanes build up circuit, version 6', 'passing_opposed', 'passive', 'in_possession', 81, 81, 'Positional Build Up Play Combinations 13', 'Xabi Alonso (Bayer Leverkusen)', 'When closed inside, open outside: a three-pass DM and AM1 combination to get round the block.', 'Blocked lanes circuit: 3 centre backs (LCB, CB, RCB), DM, two AMs and CF from the 3-4-2-1 set out in a large diamond-like shape, with 2 coaches as passive defenders blocking lanes and Alonso coaching; balls at CB.', 'With AM1 blocked, CB plays RCB who passes inside to DM as the coach approaches; DM and AM1 play a 3-pass combination; with the pass across to AM2 blocked by 2 coaches AM1 finds CF; CF one-twos with AM2 then plays LCB; LCB sets for AM2 who passes to the next player at CB.', '1-2 touches. Same 7-position rotation.', NULL, 'Closed inside means open outside.', '7 positional roles plus 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 370),
  ('Blocked lanes build up circuit, version 7', 'passing_opposed', 'passive', 'in_possession', 82, 82, 'Positional Build Up Play Combinations 14', 'Xabi Alonso (Bayer Leverkusen)', 'When closed outside, open inside: the CB uses the RCB as a link to reach AM1.', 'Blocked lanes circuit: 3 centre backs (LCB, CB, RCB), DM, two AMs and CF from the 3-4-2-1 set out in a large diamond-like shape, with 2 coaches as passive defenders blocking lanes and Alonso coaching; balls at CB.', 'The direct pass to AM1 is blocked so CB uses RCB as a link to move it on to AM1; the coach blocks CF so AM1 passes to AM2; AM2 sets for CF who plays LCB; LCB sets for AM2 who passes to the next player at CB.', '1-2 touches. Same 7-position rotation.', NULL, 'Closed outside means open inside.', '7 positional roles plus 2 coaches', 8, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 380),
  ('4v4+3 keep-ball through a central gate', 'positional_game', 'overload', 'in_possession', 94, 94, 'Positional Possession Games 1', 'Xabi Alonso (Bayer Leverkusen)', 'Keep the ball under pressure and split the defence by passing through a central gate.', 'Rectangle with a 2-cone gate in the middle; 4 reds (2 on each side), 4 blues inside, 3 yellow jokers (one at each end, one central); Alonso feeds from outside.', 'Alonso serves the reds, who with the jokers make a 7v4 overload, keep the ball and try to pass through the central gate; the 4 blues press together to close angles and win it. If the blues win it they swap roles and move to the sides to keep it with the jokers, so the reds must react and counter-press at once.', 'Maximum 2 touches for all.', NULL, 'React fast on losing the ball and press as a group.', '4v4+3', 11, 11, NULL, NULL, NULL, NULL, false, false, true, NULL, 390),
  ('5v5+3 build up in a 3-2 shape through the centre', 'positional_game', 'overload', 'in_possession', 95, 95, 'Positional Possession Games 2', 'Xabi Alonso (Bayer Leverkusen)', 'Build up in the 3-2 back structure, draw pressure and play through the central square to the far side.', 'Rectangle with a central square marked by cones; reds as 3 centre backs at one end and wingers, jokers as CB at one end and DM in the middle; 5 reds v 5 blues + 3 jokers.', 'Alonso serves the reds (8v5). They play through the blues'' press using the central square and the DMs to reach the other side, then come back again. Centre backs pause on the ball to draw their man and free a DM behind the first line.', '1-2 touches (max 3). Only one player per team in the central square at a time; the ball may be passed through it. If the blues win it they swap roles with the reds.', NULL, 'Back three draw in their opponent before releasing; DMs receive behind the first line of pressure.', '5v5+3', 13, 13, NULL, NULL, NULL, NULL, false, false, true, NULL, 400),
  ('Three-team end to end high-tempo possession', 'positional_game', 'overload', 'in_possession', 96, 96, 'Positional Possession Games 3', 'Xabi Alonso (Bayer Leverkusen)', 'Quick passing to break through a pressing team and switch the play to the far end.', 'Rectangle with 3 teams of 4; whites and reds each have 3 players at an end plus 1 in the middle, blues defend in the middle; Alonso feeds from the side.', 'Alonso serves the whites, who play through the blues with quick passes and use their middle player to switch it to the reds at the far end; the reds then do the same back the other way.', '2 touches maximum. After the blues make 2 interceptions they swap with the team that lost the ball.', NULL, 'Positional play, quick passes, switch the play.', '3 teams of 4 (4v4+4)', 12, 12, NULL, NULL, NULL, NULL, false, false, true, NULL, 410),
  ('5v5+3 end to end with central support play', 'positional_game', 'overload', 'in_possession', 97, 100, 'Positional Possession Games 4', 'Xabi Alonso (Bayer Leverkusen)', 'Use two central players to support and progress play from end to end, with wide players coming inside to help.', 'Rectangle with jokers at each end and one in the middle; 5 reds (4 wide, 1 central) v 5 blues + 3 jokers. Alonso first walks the players through their positions: a 3v2 at each end and a 2v1 in the centre.', 'Alonso serves the reds (8v5) who play through the blues using the two central players (a red and the middle joker) to move the ball from end to end; if the blues win it they swap with the reds and try to do the same.', 'Usually 1-2 touches, max 2. Stay in position when in possession.', NULL, 'Central pair always offer support on the diagonal, creating angles to receive away from a marker or drawing a defender then playing first time to the free partner (2v1 in the centre). Wide players do not sit in the corners: they move forward and inside to shorten the space and support. Reset positions when you regain the ball.', '5v5+3', 13, 13, NULL, NULL, NULL, NULL, false, false, true, NULL, 420),
  ('7v7+3 open up wide and play through pressure', 'positional_game', 'overload', 'in_possession', 101, 101, 'Positional Possession Games 5', 'Xabi Alonso (Bayer Leverkusen)', 'Spread out to stretch the area so the wide centre backs can open up and the team can play through and switch.', '40 x 40 yard square; reds take the 3-4-2-1 positions with LCB and RCB at the end corners, jokers acting as centre backs at each end and one in the middle; 7 reds v 7 blues + 3 jokers.', 'Alonso serves the reds (10v7); they keep the ball with the wide centre backs opening up into the corners to support, then play into the centre and quickly across to the other side.', 'If the blues win it they swap roles with the reds; if the ball stays in play the blues continue, otherwise Alonso feeds a new ball.', 'Start with unlimited touches, then limit to 2.', 'LCB and RCB open up in the corners and play into the centre; pass and switch to the other side.', '7v7+3', 17, 17, '40 x 40 yards', 36.6, 36.6, NULL, false, false, true, NULL, 430),
  ('8v8+4 possession in build up structures (20 passes = goal)', 'possession', 'overload', 'in_possession', 102, 102, 'Positional Possession Games 6', 'Xabi Alonso (Bayer Leverkusen)', 'Keep the ball within a set positional shape under pressure, rehearsing back-three and back-four build up structures.', '40 x 25 yard area; 8 reds v 8 blues + 4 jokers (one at each end, 2 in the middle); reds start in 3-4-2-1 spots (3 CBs, DM, 2 wing backs) shown by red circles.', 'Alonso serves the reds (12v8), who keep the ball against the blues'' press while staying in their shape. They also play out in a 4-1 from the end, mirroring the 4-2-4 build up shape.', 'Usually 1-2 touches, max 3. 20 passes = 1 goal. If the blues win it they swap with the reds.', NULL, NULL, '8v8+4', 20, 20, '40 x 25 yards', 36.6, 22.9, NULL, false, false, false, NULL, 440),
  ('8v8+5 possession with jokers in a plus shape', 'possession', 'overload', 'in_possession', 103, 103, 'Positional Possession Games 7', 'Xabi Alonso (Bayer Leverkusen)', 'Keep the ball using the full width and length of the area, then react fast to win it back.', '40 x 25 yard area; 8 reds v 8 blues + 5 jokers set in a plus: one at each end, one on each side, one central.', 'Alonso serves the reds (13v8) who keep the ball against the blues'' press using the whole area; if the blues win it they swap roles; if the ball stays in play the blues continue and the reds must counter-press immediately.', 'Usually 1-2 touches, max 3. If the ball goes out Alonso quickly feeds a new one.', NULL, 'Fast transition to win the ball back.', '8v8+5', 21, 21, '40 x 25 yards', 36.6, 22.9, NULL, false, false, false, NULL, 450),
  ('8v8+6 progress play with a 3-5 attacking shape', 'positional_game', 'overload', 'in_possession', 104, 104, 'Positional Possession Games 8', 'Xabi Alonso (Bayer Leverkusen)', 'Rehearse the front two lines of the 2-3-5 attacking shape while keeping and progressing the ball.', '40 x 25 yard area; 8 reds v 8 blues + 6 jokers set out 2-2-2 across the area (2 low, 2 middle, 2 high); reds in roles RCB, 2 DMs, 2 wing backs, 2 AMs and a CF.', 'Alonso serves the reds (14v8), who keep possession and move the ball forward through their 3-5 shape (from the 2-3-5) against the blues'' press.', 'Reds 2 touches, jokers 3. If the blues win it they swap roles with the reds; if the ball stays in play the blues continue, otherwise Alonso feeds a new ball.', NULL, NULL, '8v8+6', 22, 22, '40 x 25 yards', 36.6, 22.9, NULL, false, false, true, NULL, 460),
  ('6v6+6 build up in a 2-3 shape through the lines', 'positional_game', 'overload', 'in_possession', 105, 105, 'Positional Possession Games 9', 'Xabi Alonso (Bayer Leverkusen)', 'Make a 3v2 around the ball to beat the first line of pressure, then move it through the middle zone to the far end.', '40 x 35 yard area with a middle zone band; 6 reds v 6 blues + 6 jokers (2 in the low zone, 2 in the middle zone, 2 high); reds in a 2-3 shape at one end and 3-2 at the other.', 'Alonso serves in; the reds keep it on one side using the 2 low and 2 middle jokers (7v3) to create a 3v2 around the ball and play through the first line, then move the ball to the opposite end.', '1-2 touches (max 3). The 2 middle jokers stay in their zone but can be pressed. If the blues win it they swap roles with the reds; if the ball stays in play the blues continue, otherwise Alonso feeds a new ball.', NULL, 'Back three and two DMs form the 3-2 / 2-3 structures from the 3-2-5 and 2-3-5 build up shapes.', '6v6+6', 18, 18, '40 x 35 yards', 36.6, 32.0, NULL, false, false, true, NULL, 470),
  ('8v8+4 build up in a 3-2 shape through the lines', 'positional_game', 'overload', 'in_possession', 106, 109, 'Positional Possession Games 10', 'Xabi Alonso (Bayer Leverkusen)', 'Build up through pressure in a 3-2 shape, find the DMs behind the first line and play through the middle zone to the far end.', '40 x 25 yard area with a middle zone; 8 reds v 8 blues + 4 jokers (a CB joker at each end, 2 in the middle zone); reds as 3 centre backs and 2 DMs at either end.', 'Alonso serves in; the reds keep the ball at one end, build up so a DM can receive and progress it to the middle-zone jokers, then play to the far end.', 'Most players 2 touches, end jokers (CB) 3. Middle jokers stay in their zone but can be pressed. If the blues win it they swap roles.', NULL, 'Alonso''s stoppages: LCB and RCB open wide into the corners to stretch the area and make a 3-2 with the middle jokers; if an opponent closes the open wide player, play out, otherwise recycle and start again; keep positional discipline as it is a positional game, not plain keep-ball; move the ball fast from one side to the other to break the lines.', '8v8+4', 20, 20, '40 x 25 yards', 36.6, 22.9, NULL, false, false, true, NULL, 480),
  ('8v8+6 build up in a 4-2 shape through the lines', 'positional_game', 'overload', 'in_possession', 110, 110, 'Positional Possession Games 11', 'Xabi Alonso (Bayer Leverkusen)', 'Build up from a 4-2 back structure and play through the middle zone to score at the far end.', '40 x 35 yard area with a middle zone; 8 reds v 8 blues + 6 jokers (2 at each end, 2 in the middle zone); reds'' 3 CBs, LWB and 2 DMs form the 4-2.', 'Alonso serves in; the reds keep the ball, build up through pressure and combine with the middle jokers to reach the opposite end, which scores a goal.', '1-2 touches (max 3). Middle jokers stay in their zone but can be pressed. Reaching the far end = 1 goal. If the blues win it they swap roles with the reds; if the ball stays in play the blues continue, otherwise Alonso feeds a new ball.', NULL, 'Tempo and positioning.', '8v8+6', 22, 22, '40 x 35 yards', 36.6, 32.0, NULL, false, false, true, NULL, 490),
  ('Draw press, switch, half-space through ball', 'combination', 'passive', 'in_possession', 123, 123, 'Attacking Positional Patterns (3-1-5 setup): Pattern 1', 'Xabi Alonso (Bayer Leverkusen)', 'Drawing the press then switching to the half-space to release the wing back behind.', 'Attacking half in a 3-1-5 shape (LCB, CB, RCB, DM, LWB, LAM, CF, RAM, RWB) plus GK; 4 mannequins mark likely opponent spots (midfield, centre, wing backs). Four coaches act as passive defenders: 2 press the build-up, 2 defend in/near the box. Alonso feeds from the centre circle.', 'Coach plays wide to LCB, back to CB, who uses the 4v2 to find RCB. RCB carries and switches to LAM high in the left half-space; LAM slides LWB in on an inside run, and LWB squares across the box for CF while LAM, RAM and RWB attack the box.', '2 groups of 9 run the pattern alternately and jog back to their spots after each rep; coaches only block lanes and close down passively.', NULL, 'Build a 4v2 edge in the first line; switch play quickly; wing back and attacking midfielder time runs; fill near post, centre and back post.', '9 attackers + GK vs 4 passive coaches; 2 groups of 9 alternate', 10, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 500),
  ('CB carries, switch, wing back cross', 'combination', 'passive', 'in_possession', 124, 124, 'Attacking Positional Patterns (3-1-5 setup): Pattern 2', 'Xabi Alonso (Bayer Leverkusen)', 'Centre back stepping in with the ball and switching to set up a wing back cross.', 'Attacking half in a 3-1-5 shape (LCB, CB, RCB, DM, LWB, LAM, CF, RAM, RWB) plus GK; 4 mannequins mark likely opponent spots (midfield, centre, wing backs). Four coaches act as passive defenders: 2 press the build-up, 2 defend in/near the box. Alonso feeds from the centre circle.', 'Coach feeds LCB, who carries forward and switches to RAM in the right half-space. RAM carries and plays RWB in behind towards the byline; RWB crosses for LAM''s late run into the middle while RAM, CF and LWB also arrive.', '2 groups of 9 run the pattern alternately and jog back to their spots after each rep; coaches only block lanes and close down passively.', NULL, 'Build a 4v2 edge in the first line; switch play quickly; wing back and attacking midfielder time runs; fill near post, centre and back post.', '9 attackers + GK vs 4 passive coaches; 2 groups of 9 alternate', 10, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 510),
  ('DM bounce, switch, cut back for AM', 'combination', 'passive', 'in_possession', 125, 125, 'Attacking Positional Patterns (3-1-5 setup): Pattern 3', 'Xabi Alonso (Bayer Leverkusen)', 'Using the 4v2 after a bounce pass to switch and finish with a cut back.', 'Attacking half in a 3-1-5 shape (LCB, CB, RCB, DM, LWB, LAM, CF, RAM, RWB) plus GK; 4 mannequins mark likely opponent spots (midfield, centre, wing backs). Four coaches act as passive defenders: 2 press the build-up, 2 defend in/near the box. Alonso feeds from the centre circle.', 'Coach plays to DM under pressure, who sets back to CB; CB finds LCB in space. LCB carries and switches to RAM, who turns and releases RWB on a high run to the byline. RWB cuts back for RAM''s run into the box; CF, LAM and LWB support.', '2 groups of 9 run the pattern alternately and jog back to their spots after each rep; coaches only block lanes and close down passively.', NULL, 'Build a 4v2 edge in the first line; switch play quickly; wing back and attacking midfielder time runs; fill near post, centre and back post.', '9 attackers + GK vs 4 passive coaches; 2 groups of 9 alternate', 10, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 520),
  ('Double switch, LWB inside run, low cross', 'combination', 'passive', 'in_possession', 126, 126, 'Attacking Positional Patterns (3-1-5 setup): Pattern 4', 'Xabi Alonso (Bayer Leverkusen)', 'Moving the ball side to side twice to open a lane for the far wing back.', 'Attacking half in a 3-1-5 shape (LCB, CB, RCB, DM, LWB, LAM, CF, RAM, RWB) plus GK; 4 mannequins mark likely opponent spots (midfield, centre, wing backs). Four coaches act as passive defenders: 2 press the build-up, 2 defend in/near the box. Alonso feeds from the centre circle.', 'Coach plays to DM, who sets to CB; CB to LCB, who switches to RCB. RCB carries and switches again to LAM in the left half-space; LAM plays LWB in on an inside run and LWB drives a low cross for RAM at the back post.', '2 groups of 9 run the pattern alternately and jog back to their spots after each rep; coaches only block lanes and close down passively.', NULL, 'Build a 4v2 edge in the first line; switch play quickly; wing back and attacking midfielder time runs; fill near post, centre and back post.', '9 attackers + GK vs 4 passive coaches; 2 groups of 9 alternate', 10, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 530),
  ('Short build-up, CF set, third man run', 'combination', 'passive', 'in_possession', 127, 127, 'Attacking Positional Patterns (3-1-5 setup): Pattern 5', 'Xabi Alonso (Bayer Leverkusen)', 'Short passing through pressure then a forward''s set for a third man run in behind.', 'Attacking half in a 3-1-5 shape (LCB, CB, RCB, DM, LWB, LAM, CF, RAM, RWB) plus GK; 4 mannequins mark likely opponent spots (midfield, centre, wing backs). Four coaches act as passive defenders: 2 press the build-up, 2 defend in/near the box. Alonso feeds from the centre circle.', 'Coach plays to pressed LCB, back to CB, who breaks the first line into DM. DM to RCB, RCB wide to RWB. CF drifts across to receive from RWB and lays first time into RAM''s third man run behind; RAM cuts back for LAM.', '2 groups of 9 run the pattern alternately and jog back to their spots after each rep; coaches only block lanes and close down passively.', NULL, 'Build a 4v2 edge in the first line; switch play quickly; wing back and attacking midfielder time runs; fill near post, centre and back post.', '9 attackers + GK vs 4 passive coaches; 2 groups of 9 alternate', 10, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 540),
  ('Central build-up, RWB dribbles inside', 'combination', 'passive', 'in_possession', 128, 128, 'Attacking Positional Patterns (3-1-5 setup): Pattern 6', 'Xabi Alonso (Bayer Leverkusen)', 'Building through the centre and using the wing back''s inside dribble to enter the box.', 'Attacking half in a 3-1-5 shape (LCB, CB, RCB, DM, LWB, LAM, CF, RAM, RWB) plus GK; 4 mannequins mark likely opponent spots (midfield, centre, wing backs). Four coaches act as passive defenders: 2 press the build-up, 2 defend in/near the box. Alonso feeds from the centre circle.', 'Coach to LCB, back to CB, into DM, then to RCB as RAM drops wide to receive. RAM plays forward to RWB high in the half-space; RWB moves inside, beats the coach on the dribble into the box and passes across for LAM, with CF and LWB attacking the box.', '2 groups of 9 run the pattern alternately and jog back to their spots after each rep; coaches only block lanes and close down passively.', NULL, 'Build a 4v2 edge in the first line; switch play quickly; wing back and attacking midfielder time runs; fill near post, centre and back post.', '9 attackers + GK vs 4 passive coaches; 2 groups of 9 alternate', 10, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 550),
  ('Long switch to LWB, AM third man run', 'combination', 'passive', 'in_possession', 129, 129, 'Attacking Positional Patterns (3-1-5 setup): Pattern 7', 'Xabi Alonso (Bayer Leverkusen)', 'Long aerial switch followed by a third man run in behind the full back.', 'Attacking half in a 3-1-5 shape (LCB, CB, RCB, DM, LWB, LAM, CF, RAM, RWB) plus GK; 4 mannequins mark likely opponent spots (midfield, centre, wing backs). Four coaches act as passive defenders: 2 press the build-up, 2 defend in/near the box. Alonso feeds from the centre circle.', 'Coach to LCB, back to CB, into DM, then to RCB, who plays a long aerial switch to LWB. LWB slips the ball outside the full-back mannequin for LAM''s run in behind; LAM enters the box and cuts back for CF while RAM and RWB arrive.', '2 groups of 9 run the pattern alternately and jog back to their spots after each rep; coaches only block lanes and close down passively.', NULL, 'Build a 4v2 edge in the first line; switch play quickly; wing back and attacking midfielder time runs; fill near post, centre and back post.', '9 attackers + GK vs 4 passive coaches; 2 groups of 9 alternate', 10, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 560),
  ('Long switch to RWB, combine, back post cross', 'combination', 'passive', 'in_possession', 130, 130, 'Attacking Positional Patterns (3-1-5 setup): Pattern 8', 'Xabi Alonso (Bayer Leverkusen)', 'Long switch to the right wing back and a combination with the attacking midfielder''s run.', 'Attacking half in a 3-1-5 shape (LCB, CB, RCB, DM, LWB, LAM, CF, RAM, RWB) plus GK; 4 mannequins mark likely opponent spots (midfield, centre, wing backs). Four coaches act as passive defenders: 2 press the build-up, 2 defend in/near the box. Alonso feeds from the centre circle.', 'Coach to DM, who sets to CB; CB to LCB, who carries. DM hits a long aerial switch to RWB running beyond the mannequin; RAM, already shifted across, makes an incisive run behind to combine with RWB, who then crosses for LWB at the back post with CF and LAM in the box.', '2 groups of 9 run the pattern alternately and jog back to their spots after each rep; coaches only block lanes and close down passively.', NULL, 'Build a 4v2 edge in the first line; switch play quickly; wing back and attacking midfielder time runs; fill near post, centre and back post.', '9 attackers + GK vs 4 passive coaches; 2 groups of 9 alternate', 10, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 570),
  ('Long switch, DM overlap, give and go', 'combination', 'passive', 'in_possession', 132, 132, 'Attacking Positional Patterns (2-5 setup): Pattern 1', 'Xabi Alonso (Bayer Leverkusen)', 'Switching play and using a supporting midfielder''s run to get the wing back behind.', 'Attacking half with 7 players in a 2-5 shape (LDM, RDM, LWB, RWB, LAM, RAM, CF) plus GK; 7 mannequins mark the opposition midfield and back line, plus one in the box and a coach giving passive defence. Alonso feeds from the centre circle; spare players wait in DM, AM and CF spots.', 'Coach feeds RDM in the right half-space (2 touch), who hits a long aerial switch to LWB as LDM runs forward. LWB plays a give and go with LDM to get in behind and, with the coach giving passive pressure, cuts back for CF; LAM and RAM attack the box.', NULL, NULL, 'Quality and weight of the long switch; LDM times his forward run; arrive in the box together.', '7 attackers + GK vs coach and mannequins (extra players rotate in)', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Diagonal to AM, CF wall pass, shoot', 'combination', 'passive', 'in_possession', 133, 133, 'Attacking Positional Patterns (2-5 setup): Pattern 2', 'Xabi Alonso (Bayer Leverkusen)', 'Diagonal entry pass into the half-space and a wall pass with the striker to finish.', 'Attacking half with 7 players in a 2-5 shape (LDM, RDM, LWB, RWB, LAM, RAM, CF) plus GK; 7 mannequins mark the opposition midfield and back line, plus one in the box and a coach giving passive defence. Alonso feeds from the centre circle; spare players wait in DM, AM and CF spots.', 'Coach feeds LDM in the left half-space, who passes diagonally to RAM dropping into the right half-space. RAM plays a give and go with CF, who drops and returns a through ball; RAM meets it with a first time shot.', NULL, NULL, 'Weight of the return pass; RAM''s run timing; first time finish.', '7 attackers + GK vs coach and mannequins (extra players rotate in)', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 590),
  ('Diagonal to AM, CF drops, long shot', 'combination', 'passive', 'in_possession', 134, 134, 'Attacking Positional Patterns (2-5 setup): Pattern 3', 'Xabi Alonso (Bayer Leverkusen)', 'Combining between the lines to create a shot from distance.', 'Attacking half with 7 players in a 2-5 shape (LDM, RDM, LWB, RWB, LAM, RAM, CF) plus GK; 7 mannequins mark the opposition midfield and back line, plus one in the box and a coach giving passive defence. Alonso feeds from the centre circle; spare players wait in DM, AM and CF spots.', 'Coach feeds RDM, who plays diagonally to LAM dropping into the left half-space. LAM passes inside to CF, who also drops, turns, carries forward and shoots from outside the box as LAM and RAM follow in.', NULL, NULL, 'CF opens body to turn; create a shooting angle; midfielders follow for rebounds.', '7 attackers + GK vs coach and mannequins (extra players rotate in)', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 600),
  ('CF lay-off, deep third man shot', 'combination', 'passive', 'in_possession', 135, 135, 'Attacking Positional Patterns (2-5 setup): Pattern 4', 'Xabi Alonso (Bayer Leverkusen)', 'Back-to-goal lay-offs to release a deep midfielder''s third man run and shot.', 'Attacking half with 7 players in a 2-5 shape (LDM, RDM, LWB, RWB, LAM, RAM, CF) plus GK; 7 mannequins mark the opposition midfield and back line, plus one in the box and a coach giving passive defence. Alonso feeds from the centre circle; spare players wait in DM, AM and CF spots.', 'Coach feeds RDM (2 touch), who plays into CF dropping with back to goal and follows his pass. CF lays across to LAM dropping, LAM plays back across into RDM''s run, and RDM carries between two mannequins to shoot from distance; CF and RAM attack the box.', NULL, NULL, 'Pass and follow; set passes into the runner''s path; strike early from outside the box.', '7 attackers + GK vs coach and mannequins (extra players rotate in)', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 610),
  ('DM deep through ball for CF', 'combination', 'passive', 'in_possession', 136, 136, 'Attacking Positional Patterns (2-5 setup): Pattern 5', 'Xabi Alonso (Bayer Leverkusen)', 'A deep midfielder breaking the last line with a long through pass for the striker.', 'Attacking half with 7 players in a 2-5 shape (LDM, RDM, LWB, RWB, LAM, RAM, CF) plus GK; 7 mannequins mark the opposition midfield and back line, plus one in the box and a coach giving passive defence. Alonso feeds from the centre circle; spare players wait in DM, AM and CF spots.', 'Coach dribbles forward and passes to LDM, who checks away then comes at an angle to receive while LAM and CF check away from the mannequins. LDM plays a long ground through ball for CF''s run in behind; CF goes 1v1 with the GK and finishes.', NULL, NULL, 'Check away to create space; timing of the run to stay onside; composed finish.', '7 attackers + GK vs coach and mannequins (extra players rotate in)', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 620),
  ('Switch, wide through ball, cut back, 2nd ball', 'finishing', 'passive', 'in_possession', 139, 139, 'Positional Patterns + 2nd Ball Finishing: Pattern 1', 'Xabi Alonso (Bayer Leverkusen)', 'Switch of play leading to a cut back finish, then a second ball shot from a deep runner.', 'Attacking half with 7 players (LCB, RCB, DM, LWB, RWB, AM, CF) plus GK; 7 mannequins show likely midfield and back-line positions. Alonso feeds the first ball; 3 coaches (one either side of the goal, one on the halfway line) feed a second ball.', 'Coach plays to RCB (2 touch) in the half-space, who finds AM dropping between two mannequins; AM sets for DM, who switches to LWB. LWB plays forward for CF''s curved run behind, and CF cuts back for AM, who waits then attacks the box; RWB also runs in. Second ball: a coach by the goal feeds RCB''s advanced run for a touch and a long shot.', 'After the pattern finish a coach immediately plays a second ball for a shot.', NULL, 'Timing of runs into the box; react quickly to the second ball; shoot early.', '7 attackers + GK vs coach and mannequins (extra players rotate in)', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 630),
  ('Switch, give and go behind, 2nd ball', 'finishing', 'passive', 'in_possession', 140, 140, 'Positional Patterns + 2nd Ball Finishing: Pattern 2', 'Xabi Alonso (Bayer Leverkusen)', 'Wing back combining with the striker to get behind and cross, plus a second ball shot.', 'Attacking half with 7 players (LCB, RCB, DM, LWB, RWB, AM, CF) plus GK; 7 mannequins show likely midfield and back-line positions. Alonso feeds the first ball; 3 coaches (one either side of the goal, one on the halfway line) feed a second ball.', 'Same start: RCB to AM dropping, set to DM, switch to LWB. LWB plays a give and go with CF to get in behind and drives a low cross for AM, with the coach defending passively; RWB attacks the box. Second ball: the halfway coach feeds CF, who carries forward and shoots from outside the box.', 'After the pattern finish a coach immediately plays a second ball for a shot.', NULL, 'Timing of runs into the box; react quickly to the second ball; shoot early.', '7 attackers + GK vs coach and mannequins (extra players rotate in)', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 640),
  ('RWB one-two, long switch, cut back', 'finishing', 'passive', 'in_possession', 141, 141, 'Positional Patterns + 2nd Ball Finishing: Pattern 3', 'Xabi Alonso (Bayer Leverkusen)', 'Long switch followed by a wall pass in behind and a near-post finish, plus a second ball shot.', 'Attacking half with 7 players (LCB, RCB, DM, LWB, RWB, AM, CF) plus GK; 7 mannequins show likely midfield and back-line positions. Alonso feeds the first ball; 3 coaches (one either side of the goal, one on the halfway line) feed a second ball.', 'Coach plays to RCB, who exchanges a one-two with RWB and hits a long aerial switch to LWB. LWB plays a one-touch give and go with CF moving across, then cuts back for AM''s curved near-post run with the coach defending passively; RWB attacks the box. Second ball: the halfway coach feeds CF for a carry and long shot.', 'After the pattern finish a coach immediately plays a second ball for a shot.', NULL, 'Timing of runs into the box; react quickly to the second ball; shoot early.', '7 attackers + GK vs coach and mannequins (extra players rotate in)', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 650),
  ('Long switch, first-time through ball, cut back', 'finishing', 'passive', 'in_possession', 142, 142, 'Positional Patterns + 2nd Ball Finishing: Pattern 4', 'Xabi Alonso (Bayer Leverkusen)', 'First-time pass in behind after a switch, a cut back finish and a second ball shot.', 'Attacking half with 7 players (LCB, RCB, DM, LWB, RWB, AM, CF) plus GK; 7 mannequins show likely midfield and back-line positions. Alonso feeds the first ball; 3 coaches (one either side of the goal, one on the halfway line) feed a second ball.', 'Coach plays to RCB, one-two with RWB, then a long aerial switch to LWB. LWB plays first time in behind for AM''s curved run into the box; AM cuts back for CF arriving at the penalty spot past a passive coach. Second ball: the halfway coach feeds RWB, who drops, receives, drives at the box and shoots.', 'After the pattern finish a coach immediately plays a second ball for a shot.', NULL, 'Timing of runs into the box; react quickly to the second ball; shoot early.', '7 attackers + GK vs coach and mannequins (extra players rotate in)', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 660),
  ('Cross-field pass, cross and three runs', 'finishing', 'passive', 'in_possession', 144, 144, 'Attacking and Finishing: Practice 1', 'Xabi Alonso (Bayer Leverkusen)', 'Receiving a long cross-field pass wide and delivering for coordinated runs into the box.', 'Coach stands deep in the opposite half-space fed by another coach; a wide player (A, LWB) waits by a marked target zone near the left touchline; 3 runners outside the box; one coach defends passively; GK in goal.', 'Coach plays a long cross-field ball that A controls inside the target zone, then A crosses. B attacks the near post, D the 6-yard line, C bends a run to the back post.', 'Long pass must land in the target zone.', 'Vary the runs and mix ground and aerial crosses; repeat from the right side.', 'A times his movement to control in the zone; runners split near, middle and far.', '1 wide player + 3 runners + GK + coaches', 5, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 670),
  ('Crossing competition, four deliveries', 'finishing', 'passive', 'in_possession', 145, 145, 'Attacking and Finishing: Practice 2', 'Xabi Alonso (Bayer Leverkusen)', 'Attacking crosses of different types with coordinated runs, as a team competition.', 'Wide crossers on the right with a coach; 3 teams of 4 (e.g. yellow, blue, pink) wait outside the box; 3 mannequins in the box; GK in goal.', 'Teams take turns making coordinated runs into different zones of the box. The wide players rotate four deliveries: one-two with the coach then cross; return pass, touch and cross; out-swinging cross from deep; in-swinging cross from high on the other flank.', 'A coach counts goals per team; most goals wins.', NULL, 'Coordinate runs so all areas of the box are covered.', '3 teams of 4 + wide crossers + GK', 14, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 680),
  ('Flank combination, cross + 3v3 transition', 'transition', 'opposed', 'in_possession', 146, 146, 'Attacking and Finishing: Practice 3', 'Xabi Alonso (Bayer Leverkusen)', 'A flank combination into a 3v3 finish in the box, followed by a counter-attack transition.', 'Half pitch with a goal on the end line and a second goal around the centre; build-up players (CB, RCB, LCB, LWB, AM etc.) start on the flanks; 3 yellow attackers vs 3 blue defenders in the box; coaches with balls.', 'Coach passes to RCB and presses at once; the ball is worked across to LWB, who plays a give and go with AM to get behind and crosses low. 3 yellows attack near post, centre and far post against 3 blues defending. Second ball: a coach in the box gives a blue a ball to counter 3v3 at the opposite goal.', NULL, 'Once done, Alonso restarts and the combination is run on the right side.', 'Runs to near post, centre and far post; immediate switch of mindset after the cross.', 'Build-up group + 3v3 in box + GKs', 12, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 690),
  ('Three-team 4v4 winner stays on', 'small_sided_game', 'opposed', NULL, 149, 149, 'Positional Training Games: Game 1', 'Xabi Alonso (Bayer Leverkusen)', 'High intensity, high tempo play with quick scoring and fast transitions.', 'Area from the edge of one box to beyond halfway with two full goals and GKs; three teams of 4, the third waiting outside.', 'Normal 4v4 with GKs, started by a GK with short distribution. Teams look to score fast (early shots); the team that loses the ball counter-presses to win it back.', 'Winner stays on: the scoring team stays and the beaten team rotates out for the waiting team. Restart from the waiting team''s GK; ball out goes to the other GK; coaches count the score.', NULL, 'Speed of play; shoot early; react instantly when the ball is lost.', '3 teams of 4 + 2 GKs', 14, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 700),
  ('6v7 build-up vs compact middle block', 'transition', 'opposed', 'in_possession', 150, 150, 'Positional Training Games: Game 2', 'Xabi Alonso (Bayer Leverkusen)', 'Building up from the back around a compact mid-block and switching play to progress.', 'Large area: reds + GK build towards a big goal with GK; the blues defend in a compact central zone (marked box) and counter to 2 small goals on the reds'' end line.', 'Coach feeds the reds, who build up with their GK, moving the ball from one side to the other to stretch the block and progress to score in the big goal. Blues press, win the ball and score in either small goal.', 'Coach plays a new ball after each phase.', NULL, 'Pass into the space under pressure; switch to the far side; recover fast if the ball is lost.', '6 + GK vs 7', 15, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 710),
  ('Zonal 8v8+1 joker build-up game', 'conditioned_game', 'overload', 'in_possession', 151, 151, 'Positional Training Games: Game 3', 'Xabi Alonso (Bayer Leverkusen)', 'Playing through pressure in build-up and combining from defence to attack.', 'Half to two-thirds of a pitch split into a build-up half and an attacking half with a central joker zone; two goals with GKs; 4 reds v 4 blues in each half plus a yellow joker who acts as DM for the team in possession.', 'The GK starts and the reds build out 4v4 in the low zone, aiming to find the joker in the joker zone (after that one blue may drop to press him). The joker then joins the 4 attackers, with RCB also stepping up, to make a 4v4+2 attack.', 'If blues win the ball or it goes out, their GK restarts and roles reverse. Both teams use the 4-2-4 build-up shape.', NULL, 'Draw pressure then play into the joker; support quickly to create the overload.', '8v8 +1 joker + 2 GKs', 19, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 720),
  ('9v9+1 six-goal game, offside', 'conditioned_game', 'overload', 'in_possession', 152, 152, 'Positional Training Games: Game 4', 'Xabi Alonso (Bayer Leverkusen)', 'Breaking lines of pressure and getting in behind to score.', 'Large area with 3 small goals on each end line and an end zone in front of each that players cannot enter; 9 reds v 9 blues plus a yellow joker playing DM for the team in possession.', 'Coach starts each phase; teams build up in a 3-4-2-1 (4-2-4 in possession) and look to break lines with quick combinations, through passes or switches, then score before the end zone.', 'Offside applies. No player may enter the end zones. Coach plays a new ball when it goes out.', NULL, 'Switch to the weak side; time runs to beat the offside line; finish early.', '9v9 +1 joker', 19, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 730),
  ('Zonal 9v9 with 2nd ball counter', 'conditioned_game', 'overload', 'in_possession', 153, 153, 'Positional Training Games: Game 5', 'Xabi Alonso (Bayer Leverkusen)', 'Combining from defence to attack through zones, then reacting to a counter-attack.', 'Pitch with GKs and goals split into a build-up zone, middle zone and attacking zone; reds start 5v2 in the build-up zone, 3 red attackers v 4 blue defenders in the attacking zone; one wing back starts deep, the other in the middle zone.', 'Reds play through the 2 blue forwards from the 5v2, bypass the 3 blue midfielders and move the ball into the attacking zone, where RWB, DM and one blue midfielder join to make 5v5.', 'Interceptions by the blue midfielders must be avoided. If blues win it or the ball goes out, roles switch. 2nd ball: the coach starts a counter-attack for the other team.', NULL, 'Draw the first line, then release quickly forward; supporting runs to create the 5v5.', '9v9 + 2 GKs', 20, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 740),
  ('9v9+2 six-goal game, changing zones', 'conditioned_game', 'overload', 'in_possession', 154, 154, 'Positional Training Games: Game 6', 'Xabi Alonso (Bayer Leverkusen)', 'Breaking lines and creating scoring chances under changing conditions.', 'Large area with 3 small goals on each end line, an end zone and a build-up zone at each end; 9 reds v 9 blues plus 2 jokers; 2 coaches with balls.', 'Reds start from a coach pass and build through combination play to score. Coach changes shapes during play (e.g. 4-2-3 to the 4-2-4 build-up) and resizes the build-up zone.', 'Start: no defenders allowed in the build-up zone and goals only from inside the end zone. Restarts always from the coaches.', 'Later defenders may press high in the build-up zone and goals must come from outside the end zone.', 'Get back into positions; break lines quickly.', '9v9 +2 jokers', 20, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 750),
  ('9v9+1 GKs game, pressing zone rules', 'conditioned_game', 'overload', 'in_possession', 155, 155, 'Positional Training Games: Game 7', 'Xabi Alonso (Bayer Leverkusen)', 'Breaking pressure from the GK and creating chances, with pressing rules that change.', 'Pitch with two goals and GKs and a pressing rules zone at each end; 9 reds v 9 blues plus 1 joker (DM); both teams 3-4-2-1, 4-2-4 in possession.', 'Reds build from short GK distribution and combine to break lines and score; if blues win it they attack.', 'Start: no defenders in the pressing rules zone. Restarts from the GK or a coach''s ball.', 'Progress to allowing 1, then 2 defenders to press in the zone.', 'Short build-up under increasing pressure; combine to break lines.', '9v9 +1 joker + 2 GKs', 21, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 760),
  ('Out-swinging corners, timed runs', 'set_piece', 'unopposed', 'set_piece', 157, 157, 'Attacking Set Plays: Practice 1', 'Xabi Alonso (Bayer Leverkusen)', 'Timing and coordination of runs into the box from out-swinging corners.', '3 corner takers; 4 attackers at the edge of the box (3 run at a time plus a rotating player); mannequins and GK.', 'A runs first to the near post, B follows to the middle, C goes to the back post; the corner is aimed at the marked target area.', 'Taker raises one arm to signal an out-swinging cross; a target area is marked.', 'Repeat from the other side.', 'Runs staggered in sequence: near post first, then middle, then back post.', '3 takers + 4 runners + GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 770),
  ('Byline free kicks, timed runs', 'set_piece', 'unopposed', 'set_piece', 158, 158, 'Attacking Set Plays: Practice 2', 'Xabi Alonso (Bayer Leverkusen)', 'Timing runs from wide free kicks close to the byline.', '3 takers on a wide free-kick spot near the byline; 4 attackers at the edge of the box (3 run, 1 rotates); mannequins and GK.', 'A to the near post, B to the middle, C to the back post; the out-swinging ball is aimed at the target area.', 'Taker raises one arm to signal an out-swinging cross; a target area is marked.', 'Repeat from the other side.', 'Runs staggered in sequence: near post first, then middle, then back post.', '3 takers + 4 runners + GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 780),
  ('Wide free kicks level with penalty spot', 'set_piece', 'unopposed', 'set_piece', 159, 159, 'Attacking Set Plays: Practice 3', 'Xabi Alonso (Bayer Leverkusen)', 'Timing runs from wide free kicks level with the penalty spot.', '3 takers out wide level with the penalty spot; 4 attackers at the edge of the box (3 run, 1 rotates); mannequins set further from goal; GK.', 'A near post, B middle, C back post onto an out-swinging delivery into the target area.', 'Taker raises one arm to signal an out-swinging cross; a target area is marked.', 'Repeat from the other side.', 'Runs staggered in sequence: near post first, then middle, then back post.', '3 takers + 4 runners + GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 790),
  ('Wide free kicks level with box edge', 'set_piece', 'passive', 'set_piece', 160, 160, 'Attacking Set Plays: Practice 4', 'Xabi Alonso (Bayer Leverkusen)', 'Timing runs from wide free kicks level with the edge of the box.', '3 takers out wide level with the edge of the box; 4 runners plus a coach as a passive defender blocking runs; mannequins and GK.', 'A near post, B middle, C and D to the back post onto an out-swinging delivery into the target area.', 'Taker raises one arm to signal an out-swinging cross; a target area is marked.', 'Repeat from the other side.', 'Runs staggered in sequence: near post first, then middle, then back post.', '3 takers + 4 runners + coach + GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 800),
  ('In-swinging free kicks, five runners', 'set_piece', 'passive', 'set_piece', 161, 161, 'Attacking Set Plays: Practice 5', 'Xabi Alonso (Bayer Leverkusen)', 'Coordinated runs to attack in-swinging wide free kicks.', '4 takers on wide free kicks; 5 runners at the edge of the box plus 2 coaches as passive defenders; mannequins and GK.', 'A near post, B middle, C and D back post, E covers the back post for overhit balls; the in-swinger is aimed at the target area.', 'In-swinging delivery into a marked target area.', 'Repeat from the right side with the other group running in.', 'Runs staggered in sequence: near post first, then middle, then back post.', '4 takers + 5 runners + 2 coaches + GK', 10, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 810),
  ('Throw-in turn, cross and runs', 'set_piece', 'passive', 'set_piece', 162, 162, 'Attacking Set Plays: Practice 6', 'Xabi Alonso (Bayer Leverkusen)', 'Receiving a throw-in under pressure, turning and crossing for coordinated runs.', '3 reds out wide vs 2 coaches (close marking, passive); 6 runners in and around the box plus 2 passive coaches; mannequins and GK.', 'One player throws to a team-mate, who turns under passive pressure and crosses into the target area. A near post, B middle, C and D back post, E covers the back post, F stays on the edge of the box.', 'Receiver must turn away from the passive marker before crossing.', 'Next throw-in from the left with the other group crossing and finishing.', 'Runs staggered in sequence: near post first, then middle, then back post.', '3 throw-in players + 6 runners + 4 coaches + GK', 10, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 820)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'xabi-alonso-82-passing-positional-possession-games-patterns-and-attacking-practi') b;
INSERT INTO schema_migrations (filename) VALUES ('5004-exercises-book-xabi-alonso-82-passing-positional-possession-games-patterns-.sql') ON CONFLICT DO NOTHING;
